    const fontFamilyOptions=[
        ['system','Police système (auto)'],
        ['arial','Arial'],
        ['comicsans','Comic Sans MS'],
        ['courier','Courier New'],
        ['garamond','Garamond'],
        ['georgia','Georgia'],
        ['helvetica','Helvetica'],
        ['palatino','Palatino Linotype'],
        ['tahoma','Tahoma'],
        ['times','Times New Roman'],
        ['trebuchet','Trebuchet MS'],
        ['verdana','Verdana'],
    ];
    function fontFamilyValue(value){if(typeof value==='string'&&value.indexOf('local:')===0&&value.length>6)return value;return fontFamilyOptions.some(item=>item[0]===value)?value:'system';}
    function fontFamilyStack(value){
        const stacks={
            system:'system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif',
            arial:'Arial,Helvetica,sans-serif',
            helvetica:'Helvetica,Arial,sans-serif',
            georgia:'Georgia,"Times New Roman",serif',
            times:'"Times New Roman",Times,serif',
            verdana:'Verdana,Geneva,Arial,sans-serif',
            trebuchet:'"Trebuchet MS",Arial,sans-serif',
            courier:'"Courier New",Courier,monospace',
            garamond:'Garamond,Georgia,serif',
            tahoma:'Tahoma,Verdana,Arial,sans-serif',
            palatino:'"Palatino Linotype","Book Antiqua",Georgia,serif',
            comicsans:'"Comic Sans MS","Comic Sans",cursive,sans-serif',
        };
        // Police détectée dynamiquement via l'API Local Font Access (préfixée "local:" + nom exact de la famille).
        if(typeof value==='string'&&value.indexOf('local:')===0){
            const familyName=value.slice(6);
            return familyName?`"${familyName.replace(/"/g,'')}",Arial,Helvetica,sans-serif`:stacks.arial;
        }
        // Si la police choisie n'est pas reconnue (ex: design importé depuis un autre projet), on retombe sur la police système.
        return stacks[fontFamilyValue(value)]||stacks.system;
    }
    function personBlockSettings(personId=0){const defaults=defaultPersonBlocks.map(item=>item[0]);let settings={order:defaults,hidden:[],hideEmptyIdentity:false,widths:{}};try{settings={...settings,...JSON.parse(localStorage.getItem('genealogie-person-blocks')||'{}')};}catch(_){}if(personId){try{settings={...settings,...JSON.parse(localStorage.getItem(`genealogie-person-blocks-${personId}`)||'{}')};}catch(_){}}settings.order=[...(settings.order||[]).filter(key=>defaults.includes(key)),...defaults.filter(key=>!(settings.order||[]).includes(key))];settings.hidden=(settings.hidden||[]).filter(key=>defaults.includes(key));settings.hideEmptyIdentity=!!settings.hideEmptyIdentity;settings.widths=Object.fromEntries(Object.entries(settings.widths||{}).filter(([key,value])=>defaults.includes(key)&&personBlockWidthChoices.some(choice=>choice[0]===String(value))));defaults.forEach(key=>{if(!settings.widths[key])settings.widths[key]=defaultPersonBlockSpans[key]||'12';});return settings;}
    function savePersonBlockSettings(settings,personId=0){const key=personId?`genealogie-person-blocks-${personId}`:'genealogie-person-blocks';localStorage.setItem(key,JSON.stringify({order:settings.order,hidden:settings.hidden||[],widths:settings.widths||{},hideEmptyIdentity:!!settings.hideEmptyIdentity}));}
    function dashboardWidgetId(type){return `${type}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;}
    function dashboardWidgetLabel(type){return (defaultDashboardBlocks.find(item=>item[0]===type)||[,type])[1];}
    function dashboardNewWidget(type,source={}){
        const width=String(source.width||defaultDashboardBlockSpans[type]||'6');
        const limit=defaultDashboardBlockLimits[type]?Math.max(1,Math.min(80,Number(source.limit||defaultDashboardBlockLimits[type])||defaultDashboardBlockLimits[type])):0;
        return {id:source.id||dashboardWidgetId(type),type,width:personBlockWidthChoices.some(choice=>choice[0]===width)?width:(defaultDashboardBlockSpans[type]||'6'),limit,config:{...(source.config||{})}};
    }
    function dashboardNormalizeWidget(widget){
        const defaults=defaultDashboardBlocks.map(item=>item[0]);
        if(!widget||!defaults.includes(widget.type))return null;
        return dashboardNewWidget(widget.type,widget);
    }
    function dashboardBlockSettings(){
        const defaults=defaultDashboardBlocks.map(item=>item[0]);
        let stored={};
        try{stored=JSON.parse(localStorage.getItem('genealogie-dashboard-blocks')||'{}')||{};}catch(_){stored={};}
        if(Array.isArray(stored.widgets)){
            const widgets=stored.widgets.map(dashboardNormalizeWidget).filter(Boolean);
            return {widgets};
        }
        const order=Array.isArray(stored.order)?stored.order:[];
        const hidden=Array.isArray(stored.hidden)?stored.hidden:[];
        const legacyOrder=[...order.filter(key=>defaults.includes(key)),...defaults.filter(key=>!order.includes(key))];
        const widgets=legacyOrder.filter(key=>!hidden.includes(key)).map(key=>dashboardNewWidget(key,{width:stored.widths?.[key],limit:stored.limits?.[key]}));
        return {widgets};
    }
