        const budgetActionsHtml=type==='research_budget'?`<div class="page-actions" style="margin-top:1rem"><button type="button" class="button" id="add-budget-item">+ Dépense / abonnement</button></div><form id="research-budget-form" class="maintenance-panel compact reminder-create-form" hidden><input type="hidden" name="id" value=""><div class="form-grid"><label>Titre<input name="title" required placeholder="Abonnement Geneanet, acte payant…"></label><label>Catégorie<select name="category">${budgetCategories.map(([value,label])=>`<option value="${value}">${escapeHtml(label)}</option>`).join('')}</select></label><label>Montant<input name="amount" type="number" step="0.01" min="0" placeholder="0,00"></label><label>Devise<input name="currency" value="EUR" maxlength="8"></label><label>Date dépense<input name="expense_date" type="date"></label><label>Renouvellement<input name="renewal_date" type="date"></label><label>Fournisseur<input name="vendor" placeholder="Filae, Geneanet, AD…"></label><label>Note<input name="notes" placeholder="Détail utile…"></label></div><div class="page-actions"><button class="button" type="submit" id="research-budget-submit">Enregistrer</button><button class="button secondary" type="button" id="cancel-budget-item">Annuler</button></div></form><div id="research-budget-summary" class="reminder-summary-boxes"></div>`:'';
